  public var CREATED_AT: String? { let o = _accessor.offset(VT.CREATED_AT); return o == 0 ? nil : _accessor.string(at: o) }
  public var CREATED_ATSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.CREATED_AT) }
  ///  Last update timestamp, RFC 3339 UTC.
  public var UPDATED_AT: String? { let o = _accessor.offset(VT.UPDATED_AT); return o == 0 ? nil : _accessor.string(at: o) }
  public var UPDATED_ATSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.UPDATED_AT) }
  ///  Optional Ed25519 signature bytes over the canonical threat lane payload.
  public var SIGNATURE: FlatbufferVector<UInt8> { return _accessor.vector(at: VT.SIGNATURE, byteSize: 1) }
  public func withUnsafePointerToSignature<T>(_ body: (UnsafeRawBufferPointer, Int) throws -> T) rethrows -> T? { return try _accessor.withUnsafePointerToSlice(at: VT.SIGNATURE, body: body) }
  public static func startTHP(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 15) }
  public static func add(THP_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: THP_ID, at: VT.THP_ID) }
  public static func add(NAME: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: NAME, at: VT.NAME) }
  public static func add(DESCRIPTION: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: DESCRIPTION, at: VT.DESCRIPTION) }
  public static func add(CATEGORY: thpThreatCategory, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CATEGORY.rawValue, def: 0, at: VT.CATEGORY) }
  public static func add(ACCESS_TIER: thpAccessTier, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ACCESS_TIER.rawValue, def: 0, at: VT.ACCESS_TIER) }
  public static func add(ACTIVE: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ACTIVE, def: true,
   at: VT.ACTIVE) }
  public static func add(LINKED_SCHEMA: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: LINKED_SCHEMA, at: VT.LINKED_SCHEMA) }
  public static func add(LINKED_RECORD_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: LINKED_RECORD_ID, at: VT.LINKED_RECORD_ID) }
  public static func add(LINKED_NORAD_CAT_ID: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: LINKED_NORAD_CAT_ID, def: 0, at: VT.LINKED_NORAD_CAT_ID) }
  public static func addVectorOf(ADDITIONAL_REFS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ADDITIONAL_REFS, at: VT.ADDITIONAL_REFS) }
  public static func addVectorOf(PARAMETERS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PARAMETERS, at: VT.PARAMETERS) }
  public static func add(PROVENANCE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PROVENANCE, at: VT.PROVENANCE) }
  public static func add(CREATED_AT: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: CREATED_AT, at: VT.CREATED_AT) }
  public static func add(UPDATED_AT: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: UPDATED_AT, at: VT.UPDATED_AT) }
  public static func addVectorOf(SIGNATURE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SIGNATURE, at: VT.SIGNATURE) }
  public static func endTHP(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); fbb.require(table: end, fields: [4, 6, 26]); return end }
  public static func createTHP(
    _ fbb: inout FlatBufferBuilder,
    THP_IDOffset THP_ID: Offset,
    NAMEOffset NAME: Offset,
    DESCRIPTIONOffset DESCRIPTION: Offset = Offset(),
    CATEGORY: thpThreatCategory = .unspecified,
    ACCESS_TIER: thpAccessTier = .open_,
    ACTIVE: Bool = true,
    LINKED_SCHEMAOffset LINKED_SCHEMA: Offset = Offset(),
    LINKED_RECORD_IDOffset LINKED_RECORD_ID: Offset = Offset(),
    LINKED_NORAD_CAT_ID: UInt32 = 0,
    ADDITIONAL_REFSVectorOffset ADDITIONAL_REFS: Offset = Offset(),
    PARAMETERSVectorOffset PARAMETERS: Offset = Offset(),
    PROVENANCEOffset PROVENANCE: Offset,
    CREATED_ATOffset CREATED_AT: Offset = Offset(),
    UPDATED_ATOffset UPDATED_AT: Offset = Offset(),
    SIGNATUREVectorOffset SIGNATURE: Offset = Offset()
  ) -> Offset {
    let __start = THP.startTHP(&fbb)
    THP.add(THP_ID: THP_ID, &fbb)
    THP.add(NAME: NAME, &fbb)
    THP.add(DESCRIPTION: DESCRIPTION, &fbb)
    THP.add(CATEGORY: CATEGORY, &fbb)
    THP.add(ACCESS_TIER: ACCESS_TIER, &fbb)
    THP.add(ACTIVE: ACTIVE, &fbb)
    THP.add(LINKED_SCHEMA: LINKED_SCHEMA, &fbb)
    THP.add(LINKED_RECORD_ID: LINKED_RECORD_ID, &fbb)
    THP.add(LINKED_NORAD_CAT_ID: LINKED_NORAD_CAT_ID, &fbb)
    THP.addVectorOf(ADDITIONAL_REFS: ADDITIONAL_REFS, &fbb)
    THP.addVectorOf(PARAMETERS: PARAMETERS, &fbb)
    THP.add(PROVENANCE: PROVENANCE, &fbb)
    THP.add(CREATED_AT: CREATED_AT, &fbb)
    THP.add(UPDATED_AT: UPDATED_AT, &fbb)
    THP.addVectorOf(SIGNATURE: SIGNATURE, &fbb)
    return THP.endTHP(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.THP_ID, fieldName: "THP_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.NAME, fieldName: "NAME", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.DESCRIPTION, fieldName: "DESCRIPTION", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.CATEGORY, fieldName: "CATEGORY", required: false, type: thpThreatCategory.self)
    try _v.visit(field: VT.ACCESS_TIER, fieldName: "ACCESS_TIER", required: false, type: thpAccessTier.self)
    try _v.visit(field: VT.ACTIVE, fieldName: "ACTIVE", required: false, type: Bool.self)
    try _v.visit(field: VT.LINKED_SCHEMA, fieldName: "LINKED_SCHEMA", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.LINKED_RECORD_ID, fieldName: "LINKED_RECORD_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.LINKED_NORAD_CAT_ID, fieldName: "LINKED_NORAD_CAT_ID", required: false, type: UInt32.self)
    try _v.visit(field: VT.ADDITIONAL_REFS, fieldName: "ADDITIONAL_REFS", required: false, type: ForwardOffset<Vector<ForwardOffset<THPReference>, THPReference>>.self)
    try _v.visit(field: VT.PARAMETERS, fieldName: "PARAMETERS", required: false, type: ForwardOffset<Vector<ForwardOffset<THPParameter>, THPParameter>>.self)
    try _v.visit(field: VT.PROVENANCE, fieldName: "PROVENANCE", required: true, type: ForwardOffset<PVN>.self)
    try _v.visit(field: VT.CREATED_AT, fieldName: "CREATED_AT", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.UPDATED_AT, fieldName: "UPDATED_AT", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SIGNATURE, fieldName: "SIGNATURE", required: false, type: ForwardOffset<Vector<UInt8, UInt8>>.self)
    _v.finish()
  }
